const input = $json || {};
const body = input.body || input;
const headers = input.headers || {};

const expectedToken = (process.env.AUTOBAY_BRIDGE_TOKEN || '').trim();
const authHeader = String(headers.authorization || headers.Authorization || '').trim();

if (expectedToken) {
  const expectedHeader = `Bearer ${expectedToken}`;
  if (authHeader !== expectedHeader) {
    return [{
      json: {
        http_code: 401,
        ok: false,
        error: 'Unauthorized bridge token',
        platform: body.platform || 'unknown'
      }
    }];
  }
}

const platform = body.platform || 'unknown';
const caption = String(body.caption || '');
const hashtags = Array.isArray(body.hashtags) ? body.hashtags : [];
const mediaUrls = Array.isArray(body.media_urls) ? body.media_urls : [];
const publishId = `pub_${Date.now()}`;

return [{
  json: {
    http_code: 200,
    ok: true,
    platform,
    publish_id: publishId,
    caption_length: caption.length,
    hashtag_count: hashtags.length,
    media_count: mediaUrls.length,
    message: 'Accepted by n8n bridge'
  }
}];
